package com.mushafi.app;
import android.app.job.*;
import android.content.*;
import android.os.*;
import com.google.firebase.*;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import java.util.*;

/** Durable retry without requiring another device, a WebView, or an open screen. */
public final class CloudSyncJobService extends JobService {
 static volatile boolean uploading;
 private static final int JOB=8021;private boolean stopped;
 static void schedule(Context c){try{JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);for(JobInfo pending:jobs.getAllPendingJobs())if(pending.getId()==JOB)return;jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,CloudSyncJobService.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setMinimumLatency(1000).setBackoffCriteria(10000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());}catch(Exception ignored){}}
 @Override public boolean onStartJob(JobParameters params){stopped=false;if(uploading){new Handler(Looper.getMainLooper()).postDelayed(()->{if(!stopped)jobFinished(params,true);},1000);return true;}try{
  if(FirebaseApp.getApps(this).isEmpty())FirebaseApp.initializeApp(this);FirebaseAuth auth=FirebaseAuth.getInstance();FirebaseUser user=auth.getCurrentUser();if(user==null)return false;final String uid=user.getUid(),prefix=uid+"_";android.content.SharedPreferences prefs=getSharedPreferences("cloud_sync",0);String input=prefs.getString(prefix+"pending","");if(input.isEmpty()||prefs.getBoolean(prefix+"deletePending",false))return false;
  if(CloudSyncController.retryLive()){new Handler(Looper.getMainLooper()).postDelayed(()->{if(!stopped)jobFinished(params,true);},1000);return true;}
  uploading=true;String op=prefs.getString(prefix+"op","");if(op.isEmpty()){op=CloudPayloadMerge.nextOperation(prefs);prefs.edit().putString(prefix+"op",op).commit();}final String operation=op;String baseline=prefs.getString(prefix+"basePayload",prefs.getString(prefix+"ackPayload",CloudPayloadMerge.EMPTY));FirebaseFirestore db=FirebaseFirestore.getInstance();DocumentReference ref=db.document("users/"+uid+"/mushafi/state");
  db.runTransaction(tx->{if(stopped||auth.getCurrentUser()==null||!uid.equals(auth.getCurrentUser().getUid())||prefs.getBoolean(prefix+"deletePending",false))throw new FirebaseFirestoreException("session changed",FirebaseFirestoreException.Code.ABORTED);try{DocumentSnapshot old=tx.get(ref);Long rev=old.getLong("revision");long current=rev==null?0:rev;String server=old.getString("payload");if(CloudPayloadMerge.applied(server,operation))return new org.json.JSONObject().put("revision",current).put("payload",server);long next=current+1;String merged=CloudPayloadMerge.record(CloudPayloadMerge.merge(baseline,input,server),server,operation);if(merged.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>750000)throw new FirebaseFirestoreException("payload too large",FirebaseFirestoreException.Code.INVALID_ARGUMENT);Map<String,Object> values=new HashMap<>();values.put("payload",merged);values.put("revision",next);values.put("updatedAt",FieldValue.serverTimestamp());values.put("device",prefs.getString("device","background"));tx.set(ref,values);return new org.json.JSONObject().put("revision",next).put("payload",merged);}catch(org.json.JSONException e){throw new FirebaseFirestoreException("invalid payload",FirebaseFirestoreException.Code.INVALID_ARGUMENT,e);}}).addOnSuccessListener(result->{uploading=false;boolean more=false;if(auth.getCurrentUser()!=null&&uid.equals(auth.getCurrentUser().getUid())&&!prefs.getBoolean(prefix+"deletePending",false)){long rev=result.optLong("revision");android.content.SharedPreferences.Editor edit=prefs.edit().putString(prefix+"ackPayload",result.optString("payload")).putString(prefix+"ackInput",input).putLong(prefix+"ackRevision",rev).putLong(prefix+"lastSync",System.currentTimeMillis());String latest=prefs.getString(prefix+"pending","");if(latest.equals(input)&&operation.equals(prefs.getString(prefix+"op","")))edit.remove(prefix+"pending").remove(prefix+"op").remove(prefix+"basePayload").putLong(prefix+"base",rev);else if(!latest.isEmpty()){more=true;edit.putString(prefix+"basePayload",latest.equals(input)?baseline:input).putLong(prefix+"base",rev);}edit.commit();}CloudSyncController.retryLive();if(!stopped)jobFinished(params,more);}).addOnFailureListener(error->{uploading=false;CloudSyncController.retryLive();if(!stopped)jobFinished(params,true);});return true;
 }catch(Exception e){uploading=false;return false;}}
 @Override public boolean onStopJob(JobParameters params){stopped=true;return true;}
}
